const AUTH_KEY='yhtrade.auth';
const SUPABASE_URL='https://ggzmsicyfncxtgpshphx.supabase.co';
const SUPABASE_PUBLISHABLE_KEY='sb_publishable_BVPs38_MMcmXF4sh84tSOg_CT10Jw1N';
let supabaseClient=null;
function showNotice(message,type='error'){const el=document.querySelector('#notice');if(!el)return;el.textContent=message;el.className=`notice show ${type}`}
function goAfterLogin(){location.href='index.html'}
function isSignedIn(){return localStorage.getItem(AUTH_KEY)==='signed-in'}
function requireLogin(){if(!isSignedIn())location.href='login.html'}
function loadSupabase(){return new Promise(resolve=>{if(window.supabase){supabaseClient=window.supabase.createClient(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY);resolve(supabaseClient);return}const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2';s.onload=()=>{supabaseClient=window.supabase.createClient(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY);resolve(supabaseClient)};s.onerror=()=>resolve(null);document.head.appendChild(s)})}
document.addEventListener('DOMContentLoaded',async()=>{
 const publicPages=['login.html','signup.html','find-id.html','find-password.html'];
 if(!publicPages.some(p=>location.pathname.endsWith(p)))requireLogin();
 const client=await loadSupabase();
 if(client){
  const {data}=await client.auth.getSession();
  if(data?.session){localStorage.setItem(AUTH_KEY,'signed-in');if(data.session.user?.email)localStorage.setItem('yhtrade.user',data.session.user.email)}
  client.auth.onAuthStateChange((_event,session)=>{if(session){localStorage.setItem(AUTH_KEY,'signed-in')}else if(_event==='SIGNED_OUT'){localStorage.removeItem(AUTH_KEY);localStorage.removeItem('yhtrade.user')}});
 }
 const login=document.querySelector('#loginForm');
 if(login)login.addEventListener('submit',async e=>{e.preventDefault();const id=document.querySelector('#loginId').value.trim();const pw=document.querySelector('#loginPw').value.trim();if(!id||!pw){showNotice('아이디 또는 이메일과 비밀번호를 입력해 주세요.');return}if(client){let email=id;if(!id.includes('@')){const {data,error}=await client.rpc('get_login_email',{p_username:id});if(error||!data){showNotice('등록된 아이디를 찾을 수 없습니다.');return}email=data}const {error}=await client.auth.signInWithPassword({email,password:pw});if(error){showNotice('로그인할 수 없습니다. 아이디·이메일과 비밀번호를 확인해 주세요.');return}}localStorage.setItem(AUTH_KEY,'signed-in');localStorage.setItem('yhtrade.user',id);showNotice('로그인되었습니다. 잠시 후 대시보드로 이동합니다.','ok');setTimeout(goAfterLogin,500)});
 const signout=document.querySelector('#signout');if(signout)signout.addEventListener('click',async()=>{if(client)await client.auth.signOut();localStorage.removeItem(AUTH_KEY);localStorage.removeItem('yhtrade.user');location.href='login.html'});
 const profile=document.querySelector('#profileForm');if(profile){const saved=JSON.parse(localStorage.getItem('yhtrade.profile')||'{}');const name=document.querySelector('#profileName');const phone=document.querySelector('#profilePhone');if(name)name.value=saved.name||'';if(phone)phone.value=saved.phone||'';profile.addEventListener('submit',e=>{e.preventDefault();const profileData={name:name.value.trim(),phone:phone.value.trim()};if(!profileData.name||!profileData.phone){alert('이름과 휴대폰 번호를 입력해 주세요.');return}if(!/^01[0-9]-?\d{3,4}-?\d{4}$/.test(profileData.phone.replace(/\s/g,''))){alert('휴대폰 번호를 올바르게 입력해 주세요.');return}localStorage.setItem('yhtrade.profile',JSON.stringify(profileData));alert('계정 정보가 저장되었습니다. Supabase 연결 후 문자 인증을 추가할 수 있습니다.')})}
 const findId=document.querySelector('#findIdForm');if(findId)findId.addEventListener('submit',async e=>{e.preventDefault();const contact=document.querySelector('#findIdContact')?.value.trim();if(!contact){showNotice('이메일 또는 휴대폰 번호를 입력해 주세요.');return}if(client){const {data,error}=await client.rpc('get_login_username',{p_contact:contact});if(error){showNotice('아이디 조회 기능을 준비하는 중입니다. 잠시 후 다시 시도해 주세요.');return}if(data){showNotice(`등록된 아이디는 ${data} 입니다.`,'ok')}else{showNotice('일치하는 이메일 또는 휴대폰 번호를 찾을 수 없습니다.')}}else{showNotice('Supabase 연결 후 아이디를 조회할 수 있습니다.')}});
 const findPw=document.querySelector('#findPwForm');if(findPw)findPw.addEventListener('submit',async e=>{e.preventDefault();const email=document.querySelector('#findPwEmail')?.value.trim();if(client&&email){const options=/^https?:$/.test(location.protocol)?{redirectTo:location.origin+'/login.html'}:undefined;const {error}=await client.auth.resetPasswordForEmail(email,options);if(error){showNotice('비밀번호 재설정 메일을 보낼 수 없습니다. 이메일을 확인해 주세요.');return}}showNotice('비밀번호 재설정 안내를 준비했습니다. 이메일 받은편지함을 확인해 주세요.','ok')});
 const signup=document.querySelector('#signupForm');if(signup)signup.addEventListener('submit',async e=>{e.preventDefault();const name=document.querySelector('#signupName').value.trim();const email=document.querySelector('#signupEmail').value.trim();const phone=document.querySelector('#signupPhone').value.trim();const id=document.querySelector('#signupId').value.trim();const pw=document.querySelector('#signupPw').value;const confirm=document.querySelector('#signupPwConfirm').value;const terms=document.querySelector('#signupTerms').checked;if(!name||!email||!phone||!id||!pw||!confirm){showNotice('필수 항목을 모두 입력해 주세요.');return}if(!/^01[0-9]-?\d{3,4}-?\d{4}$/.test(phone.replace(/\s/g,''))){showNotice('휴대폰 번호를 올바르게 입력해 주세요.');return}if(pw.length<8){showNotice('비밀번호는 8자 이상으로 설정해 주세요.');return}if(pw!==confirm){showNotice('비밀번호가 일치하지 않습니다.');return}if(!terms){showNotice('이용 약관에 동의해 주세요.');return}if(client){const options={data:{name,phone,username:id}};if(/^https?:$/.test(location.protocol))options.emailRedirectTo=location.origin+'/login.html';const {error}=await client.auth.signUp({email,password:pw,options});if(error){showNotice(error.message.includes('already registered')?'이미 가입된 이메일입니다.':'회원가입 중 오류가 발생했습니다.');return}localStorage.setItem('yhtrade.profile',JSON.stringify({name,phone,email,id}));showNotice('가입이 완료되었습니다. 이메일 인증 후 로그인해 주세요.','ok')}else{localStorage.setItem('yhtrade.pendingUser',JSON.stringify({name,email,phone,id,createdAt:new Date().toISOString()}));showNotice('가입 신청이 저장되었습니다. 관리자 확인 후 로그인할 수 있습니다.','ok')}setTimeout(()=>location.href='login.html',1200)});
});
